import { createHash } from 'node:crypto'
import { performance } from 'node:perf_hooks'
import os from 'node:os'
const directory = '/tmp/silk-arguments.abqEOK'
const hash = value => createHash('sha256').update(value).digest('hex')
const env = {...process.env,NODE_DISABLE_COMPILE_CACHE:'1'}
for (const key of ['NODE_OPTIONS','NODE_COMPILE_CACHE','NODE_V8_COVERAGE','SILK_NATIVE_CACHE_DIR']) delete env[key]
const fingerprint = () => {
  const paths=[]
  const visit=path=>{ for(const entry of readdirSync(path,{withFileTypes:true})){const child=path+'/'+entry.name;if(entry.isDirectory())visit(child);else if(/\.(js|ts|silk)$/.test(child))paths.push(child)} }
  for(const path of ['packages/compiler/src','packages/compiler/dist','packages/llvm/src','packages/llvm/dist','compiler/src','/tmp/silk-result-transport.MoglOG/compiler-dist']) visit(path)
  return hash(paths.sort().map(path=>path+':'+hash(readFileSync(path))).join('\n'))
}
const output={command:'packages/cli/dist/bin.js build-exe compiler/src/main.silk --source-root compiler/src --optimization debug --timings',control:'Read-only loader substitutes initial compiler dist, which already includes the preceding transient-outcome optimization. Both modes use the final LLVM implementation (entry placement is opt-in); the after compiler transports canonical aggregate arguments to synchronous Effect runners and copies them into callee-owned storage. Every control binary is checked against the original baseline.',node:process.version,cpu:os.cpus()[0]?.model,fingerprint:fingerprint(),samples:[]}
const expected=readFileSync('/tmp/silk-result-transport.MoglOG/before.ast','utf8')
for(const [index,mode] of ['before','after','after','before','before','after'].entries()){
  const binary=`${directory}/final-${index}-${mode}`
  const args=['-l',process.execPath,'--import','/tmp/silk-result-transport.MoglOG/control.mjs','packages/cli/dist/bin.js','build-exe','compiler/src/main.silk','--source-root','compiler/src','--optimization','debug','--output',binary,'--timings']
  const loadBefore=os.loadavg(),start=performance.now()
  const result=spawnSync('/usr/bin/time',args,{env:{...env,SILK_RESULT_TRANSPORT_CONTROL:mode},encoding:'utf8',timeout:180000,maxBuffer:32*1024*1024})
  const wallMs=performance.now()-start
  if(result.status!==0)throw new Error(JSON.stringify(result))
  const ast=execFileSync(binary,['compiler/src/main.silk'],{env,encoding:'utf8',timeout:60000})
  if(ast!==expected)throw new Error('AST output changed')
  const binarySha256=hash(readFileSync(binary))
  if(mode==='before' && binarySha256!==hash(readFileSync('/tmp/silk-result-transport.MoglOG/before')))throw new Error('Control binary differs from original baseline')
  if(mode==='after' && binarySha256!==hash(readFileSync(directory+'/ir-final')))throw new Error('Candidate binary differs from instruction-attribution build')
  const phases=[...(result.stdout+'\n'+result.stderr).matchAll(/^\s+([\w-]+)\s+([\d.]+)ms\s+(\d+) in \/ (\d+) out\s+(\d+) diag/gm)].map(([,name,wall,inputs,outputs,diagnostics])=>({name,wallMs:Number(wall),inputs:Number(inputs),outputs:Number(outputs),diagnostics:Number(diagnostics)}))
  const times=/([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys/.exec(result.stderr)
  if(!times||!phases.length)throw new Error('Missing timings')
  output.samples.push({index,mode,wallMs,cpuSeconds:Number(times[2])+Number(times[3]),peakRssBytes:Number(/(\d+)\s+maximum resident set size/.exec(result.stderr)?.[1]),phases,loadBefore,loadAfter:os.loadavg(),binarySha256,astSha256:hash(ast),stdout:result.stdout,stderr:result.stderr})
  writeFileSync(directory+'/paired-final.json',JSON.stringify(output,null,2)+'\n')
  console.log(`${index+1}/6 ${mode}: ${(wallMs/1000).toFixed(2)}s`)
}
if(fingerprint()!==output.fingerprint)throw new Error('Measured files changed')
output.fingerprintVerified=true
writeFileSync(directory+'/paired-final.json',JSON.stringify(output,null,2)+'\n')

