// Read-only diagnostic loader. Changes loaded module text in memory, never source/dist.
import { registerHooks, createRequire } from 'node:module'
import { writeFileSync } from 'node:fs'
const require = createRequire(process.cwd() + '/package.json')
const acorn = require('./node_modules/.pnpm/acorn@8.18.0/node_modules/acorn')
const stack = []
const builders = new Map()
const snapshots = []
const patches = []
const calls = Object.create(null)
globalThis.__irProbe = {
  enter(label) {
    stack.push(label)
    calls[label] = (calls[label] ?? 0) + 1
  },
  leave() { stack.pop() },
  instruction(draft) {
    let rows = builders.get(draft.builder)
    if (!rows) builders.set(draft.builder, rows = new Map())
    let row = rows.get(draft.functionIndex)
    if (!row) rows.set(draft.functionIndex, row = { total: 0, buckets: {}, opcodes: {} })
    row.total++
    const key = stack.filter(s => !s.startsWith('Function:')).join(' > ') || 'Other scaffolding'
    row.buckets[key] = (row.buckets[key] ?? 0) + 1
    const tag = draft.instructions.at(-1)._tag
    row.opcodes[tag] = (row.opcodes[tag] ?? 0) + 1
  },
  snapshot(builder, state) {
    const rows = builders.get(builder) ?? new Map()
    const functions = []
    for (const [index, fn] of state.functions.entries()) {
      if (!fn.body) continue
      const row = rows.get(index) ?? { total: 0, buckets: {}, opcodes: {} }
      const symbol = Buffer.from(state.globals[fn.global].name.bytes).toString('utf8')
      if (row.total !== fn.body.instructions.length)
        throw new Error(`Instruction attribution mismatch: ${symbol}: ${row.total} vs ${fn.body.instructions.length}`)
      functions.push({ symbol, ...row })
    }
    snapshots.push({ functions })
    writeFileSync(process.env.SILK_RESULT_PROBE_OUTPUT ?? '/tmp/silk-remaining-leads.TW7mcc/attribution.json', JSON.stringify({ patches, calls, snapshots }))
  },
}
const wanted = new Map([
  ['/compiler/dist/NativeOperation.js', new Map([['emit', '"Operation:" + operation._tag']])],
  ['/compiler/dist/NativeControl.js', new Map([['emit', '"Control"']])],
  ['/compiler/dist/NativePlace.js', new Map(['loadLanes', 'storeLanes', 'transfer', 'copy'].map(x => [x, JSON.stringify('Place:' + x)]))],
  ['/compiler/dist/NativeReturn.js', new Map([['emitCompletion', '"Completion"']])],
  ['/compiler/dist/NativeTermination.js', new Map([['emitTrapBlocks', '"Trap blocks"']])],
])
function wrapGenerators(source, url, definitions, bodyCallback = false) {
  const ast = acorn.parse(source, { ecmaVersion: 'latest', sourceType: 'module' })
  const edits = []
  const visit = (node, owner) => {
    if (node.type === 'VariableDeclarator' && node.id.type === 'Identifier') owner = node.id.name
    if (node.type === 'FunctionExpression' && node.generator && node.body) {
      const label = bodyCallback && node.params[0]?.name === 'body'
        ? '"Function:" + entry.symbol' : definitions?.get(owner)
      if (label) {
        edits.push([node.body.start + 1, `globalThis.__irProbe.enter(${label}); try {`])
        edits.push([node.body.end - 1, '} finally { globalThis.__irProbe.leave(); }'])
        patches.push({ url, owner: bodyCallback ? 'body' : owner })
      }
    }
    for (const value of Object.values(node)) {
      if (Array.isArray(value)) { for (const child of value) if (child?.type) visit(child, owner) }
      else if (value?.type) visit(value, owner)
    }
  }
  visit(ast)
  for (const [offset, text] of edits.sort((a, b) => b[0] - a[0])) source = source.slice(0, offset) + text + source.slice(offset)
  return source
}
function replaceOnce(source, from, to) {
  if (source.split(from).length !== 2) throw new Error('Probe anchor is not unique: ' + from)
  return source.replace(from, to)
}
registerHooks({ load(url, context, nextLoad) {
  const result = nextLoad(url, context)
  if (!url.includes('/packages/')) return result
  let source = String(result.source)
  for (const [suffix, definitions] of wanted) if (url.endsWith(suffix)) source = wrapGenerators(source, url, definitions)
  if (url.endsWith('/compiler/dist/NativeFunction.js')) {
    source = wrapGenerators(source, url, undefined, true)
    source = replaceOnce(source, 'let physicalParameter = 0;', 'globalThis.__irProbe.enter("Parameter ingress"); let physicalParameter = 0;')
    source = replaceOnce(source, 'if (entry.diagnosticParameter !== undefined)\n                physicalParameter += 2;', 'globalThis.__irProbe.leave(); if (entry.diagnosticParameter !== undefined)\n                physicalParameter += 2;')
  }
  if (url.endsWith('/llvm/dist/internal/FunctionBodyState/InstructionEncoder.js')) {
    for (const anchor of ['draft.instructions.push(instruction);', 'draft.instructions.push(makeInstruction(result, finalName));'])
      source = replaceOnce(source, anchor, anchor + ' globalThis.__irProbe.instruction(draft);')
  }
  if (url.endsWith('/llvm/dist/Bitcode.js')) {
    const anchor = "const state = yield* BuilderState.snapshot(self, 'Bitcode.encode');"
    source = replaceOnce(source, anchor, anchor + ' globalThis.__irProbe.snapshot(self, state);')
  }
  return { ...result, source }
} })
